from pathlib import Path

TOP = Path("pages/6_Top_Plays.py")
APP = Path("streamlit_app.py")
TEST = Path("tests/test_odds_credit_saver.py")

# --- Top Plays: no paid calls on page load; request only markets represented in Top 5. ---
top = TOP.read_text(encoding="utf-8")
old = 'MARKETS = "pitcher_strikeouts,pitcher_strikeouts_alternate,pitcher_outs,pitcher_outs_alternate,pitcher_hits_allowed,pitcher_hits_allowed_alternate"\n'
new = '''MAIN_MARKET_KEYS = {\n    "Strikeouts": "pitcher_strikeouts",\n    "Total Outs": "pitcher_outs",\n    "Hits Allowed": "pitcher_hits_allowed",\n}\n'''
if old not in top:
    raise SystemExit("Top Plays MARKETS anchor not found")
top = top.replace(old, new, 1)
top = top.replace('@st.cache_data(ttl=60, show_spinner=False)\ndef odds_events', '@st.cache_data(ttl=900, show_spinner=False)\ndef odds_events', 1)

old = '''@st.cache_data(ttl=60, show_spinner=False)\ndef event_props(api_key: str, event_id: str) -> dict:\n    r = requests.get(\n        f"{ODDS_API}/sports/baseball_mlb/events/{event_id}/odds",\n        params={"apiKey": api_key, "regions": "us", "markets": MARKETS, "oddsFormat": "american"},\n        timeout=20,\n    )\n    r.raise_for_status()\n    data = r.json()\n    return data if isinstance(data, dict) else {}\n'''
new = '''@st.cache_data(ttl=900, show_spinner=False)\ndef event_props(api_key: str, event_id: str, markets: tuple[str, ...]) -> tuple[dict, dict[str, int | None]]:\n    market_csv = ",".join(sorted(set(str(m) for m in markets if str(m))))\n    if not market_csv:\n        return {}, {"remaining": None, "used": None, "last": 0}\n    r = requests.get(\n        f"{ODDS_API}/sports/baseball_mlb/events/{event_id}/odds",\n        params={"apiKey": api_key, "regions": "us", "markets": market_csv, "oddsFormat": "american"},\n        timeout=20,\n    )\n    r.raise_for_status()\n    data = r.json()\n    def _header_int(name: str) -> int | None:\n        value = r.headers.get(name)\n        try:\n            return int(value) if value is not None else None\n        except (TypeError, ValueError):\n            return None\n    quota = {\n        "remaining": _header_int("x-requests-remaining"),\n        "used": _header_int("x-requests-used"),\n        "last": _header_int("x-requests-last"),\n    }\n    return (data if isinstance(data, dict) else {}), quota\n'''
if old not in top:
    raise SystemExit("Top Plays event_props anchor not found")
top = top.replace(old, new, 1)

old = '''# The board exists before any sportsbook request. Live prices are attached afterward\n# only when an exact matching line is available; they never affect rank.\nplays["Book"] = ""\nplays["Odds"] = np.nan\nplays["No-Vig Implied"] = np.nan\nplays["Edge"] = np.nan\nplays["Live Offer"] = False\ncandidate_pool = pd.DataFrame()\n\nif api_key:\n    try:\n        events = odds_events(api_key)\n        all_legs: list[dict] = []\n        scanned = set()\n        for _, play in plays.iterrows():\n            key = (numeric(play.get("Game PK")), numeric(play.get("Pitcher ID")))\n            if key in scanned:\n                continue\n            scanned.add(key)\n            snapshot = find_snapshot(history, play)\n            if snapshot is None:\n                continue\n            event_match = match_event(events, str(snapshot.get("team", "")), str(snapshot.get("opponent", "")))\n            if not event_match:\n                continue\n            try:\n                all_legs.extend(collect_legs(snapshot, event_props(api_key, str(event_match.get("id"))), history))\n            except requests.RequestException:\n                continue\n        if all_legs:\n            candidate_pool = pd.DataFrame(all_legs)\n            for idx, play in plays.iterrows():\n                matches = candidate_pool.loc[\n                    candidate_pool["Pitcher"].astype(str).eq(str(play["Pitcher"]))\n                    & candidate_pool["Market"].astype(str).eq(str(play["Market"]))\n                    & candidate_pool["Side"].astype(str).eq(str(play["Side"]))\n                    & pd.to_numeric(candidate_pool["Line"], errors="coerce").eq(float(play["Line"]))\n                ]\n                if matches.empty:\n                    continue\n                best = matches.sort_values("Odds", ascending=False).iloc[0]\n                plays.at[idx, "Book"] = best.get("Book", "")\n                plays.at[idx, "Odds"] = best.get("Odds", np.nan)\n                plays.at[idx, "No-Vig Implied"] = best.get("No-Vig Implied", np.nan)\n                plays.at[idx, "Edge"] = best.get("Edge", np.nan)\n                plays.at[idx, "Live Offer"] = True\n    except requests.RequestException as exc:\n        st.caption(f"Live sportsbook overlay unavailable right now ({type(exc).__name__}). The model Top 5 is still valid because odds do not rank it.")\nelse:\n    st.caption("Odds API key is not available, so the model Top 5 is shown without live execution prices. Ranking is unaffected.")\n'''
new = '''# The board exists before any paid sportsbook request. Credit Saver keeps paid\n# odds OFF by default and only asks for main markets represented in the Top 5.\nplays["Book"] = ""\nplays["Odds"] = np.nan\nplays["No-Vig Implied"] = np.nan\nplays["Edge"] = np.nan\nplays["Live Offer"] = False\n\nlive_state_key = f"top_plays_live_overlay:{today}"\nquota_state_key = f"top_plays_live_quota:{today}"\ncandidate_pool = pd.DataFrame(st.session_state.get(live_state_key, []))\nrequest_plan: dict[str, set[str]] = {}\nevent_snapshots: dict[str, dict[str, pd.Series]] = {}\n\nif api_key:\n    try:\n        # /events is quota-free; it only maps MLB games to Odds API event ids.\n        events = odds_events(api_key)\n        for _, play in plays.iterrows():\n            snapshot = find_snapshot(history, play)\n            if snapshot is None:\n                continue\n            event_match = match_event(events, str(snapshot.get("team", "")), str(snapshot.get("opponent", "")))\n            market_key = MAIN_MARKET_KEYS.get(str(play.get("Market", "")))\n            if not event_match or not market_key:\n                continue\n            event_id = str(event_match.get("id", ""))\n            if not event_id:\n                continue\n            request_plan.setdefault(event_id, set()).add(market_key)\n            pitcher_key = str(play.get("Pitcher ID", play.get("Pitcher", "")))\n            event_snapshots.setdefault(event_id, {})[pitcher_key] = snapshot\n    except requests.RequestException as exc:\n        st.caption(f"Quota-free event matching is unavailable right now ({type(exc).__name__}). The model Top 5 is unaffected.")\n\nestimated_credits = sum(len(markets) for markets in request_plan.values())\nif api_key and request_plan:\n    st.caption(\n        f"💳 Credit Saver: sportsbook odds are OFF until requested. Loading this Top 5 asks only for "\n        f"{estimated_credits} main market/event combination(s) in the US region — at most {estimated_credits} credits if returned. "\n        "Alternate markets are disabled by default."\n    )\n    if st.button(\n        f"💳 Load / reuse live Top 5 prices · ≤{estimated_credits} credits",\n        key="load_top_plays_live_prices",\n        help="Paid Odds API call. Results are cached for 15 minutes; clicking again inside that window reuses the cache.",\n    ):\n        all_legs: list[dict] = []\n        quota_rows: list[dict[str, int | None]] = []\n        for event_id, market_keys in request_plan.items():\n            try:\n                payload, quota = event_props(api_key, event_id, tuple(sorted(market_keys)))\n                quota_rows.append(quota)\n            except requests.RequestException as exc:\n                st.caption(f"Live price request failed for one event ({type(exc).__name__}).")\n                continue\n            for snapshot in event_snapshots.get(event_id, {}).values():\n                all_legs.extend(collect_legs(snapshot, payload, history))\n        st.session_state[live_state_key] = all_legs\n        if quota_rows:\n            actual_cost = sum(int(q.get("last") or 0) for q in quota_rows)\n            final_quota = quota_rows[-1]\n            st.session_state[quota_state_key] = {\n                "last": actual_cost,\n                "remaining": final_quota.get("remaining"),\n                "used": final_quota.get("used"),\n            }\n        st.rerun()\nelse:\n    if not api_key:\n        st.caption("Odds API key is not available, so the model Top 5 is shown without live execution prices. Ranking is unaffected.")\n\nquota_view = st.session_state.get(quota_state_key, {})\nif quota_view:\n    remaining = quota_view.get("remaining")\n    used = quota_view.get("used")\n    last = quota_view.get("last")\n    st.caption(\n        "Odds API usage from the last manual Top 5 load: "\n        + f"{last if last is not None else '—'} credit(s) · "\n        + f"{remaining if remaining is not None else '—'} remaining · "\n        + f"{used if used is not None else '—'} used this quota period."\n    )\n\nif not candidate_pool.empty:\n    for idx, play in plays.iterrows():\n        matches = candidate_pool.loc[\n            candidate_pool["Pitcher"].astype(str).eq(str(play["Pitcher"]))\n            & candidate_pool["Market"].astype(str).eq(str(play["Market"]))\n            & candidate_pool["Side"].astype(str).eq(str(play["Side"]))\n            & pd.to_numeric(candidate_pool["Line"], errors="coerce").eq(float(play["Line"]))\n        ]\n        if matches.empty:\n            continue\n        best = matches.sort_values("Odds", ascending=False).iloc[0]\n        plays.at[idx, "Book"] = best.get("Book", "")\n        plays.at[idx, "Odds"] = best.get("Odds", np.nan)\n        plays.at[idx, "No-Vig Implied"] = best.get("No-Vig Implied", np.nan)\n        plays.at[idx, "Edge"] = best.get("Edge", np.nan)\n        plays.at[idx, "Live Offer"] = True\n'''
if old not in top:
    raise SystemExit("Top Plays automatic paid-odds block anchor not found")
top = top.replace(old, new, 1)
TOP.write_text(top, encoding="utf-8")

# --- Main Projection: manual main-market load only, max three market credits. ---
app = APP.read_text(encoding="utf-8")
app = app.replace('@st.cache_data(ttl=60,show_spinner=False)\ndef get_odds_events', '@st.cache_data(ttl=900,show_spinner=False)\ndef get_odds_events', 1)

old = '''@st.cache_data(ttl=60,show_spinner=False)\ndef get_event_props(event_id):\n    key=get_secret()\n    if not key:return [],"Odds API key not found in Streamlit secrets."\n    params={"apiKey":key,"regions":"us","markets":"pitcher_strikeouts,pitcher_strikeouts_alternate,pitcher_outs,pitcher_outs_alternate,pitcher_hits_allowed,pitcher_hits_allowed_alternate","oddsFormat":"american"}\n    try:\n        r=requests.get(f"{ODDS_API}/sports/baseball_mlb/events/{event_id}/odds",params=params,timeout=15); r.raise_for_status(); return r.json(),None\n    except requests.RequestException as e:return [],safe_odds_error(e)\n'''
new = '''MAIN_PROP_MARKETS="pitcher_strikeouts,pitcher_outs,pitcher_hits_allowed"\n\n@st.cache_data(ttl=900,show_spinner=False)\ndef get_event_props(event_id):\n    key=get_secret()\n    if not key:return [],"Odds API key not found in Streamlit secrets.",{}\n    params={"apiKey":key,"regions":"us","markets":MAIN_PROP_MARKETS,"oddsFormat":"american"}\n    try:\n        r=requests.get(f"{ODDS_API}/sports/baseball_mlb/events/{event_id}/odds",params=params,timeout=15)\n        r.raise_for_status()\n        def _h(name):\n            value=r.headers.get(name)\n            try:return int(value) if value is not None else None\n            except (TypeError,ValueError):return None\n        quota={"remaining":_h("x-requests-remaining"),"used":_h("x-requests-used"),"last":_h("x-requests-last")}\n        return r.json(),None,quota\n    except requests.RequestException as e:return [],safe_odds_error(e),{}\n'''
if old not in app:
    raise SystemExit("Projection get_event_props anchor not found")
app = app.replace(old, new, 1)

old = '''odds_events,odds_err=get_odds_events(); odds_event_id=find_odds_event(odds_events,game)\nif odds_event_id: odds_payload,prop_err=get_event_props(odds_event_id); odds_err=prop_err if prop_err else odds_err\nelse: odds_payload=[]; odds_err=odds_err if odds_err else "No matching Odds API event found for this MLB game."\nodds_rows=extract_player_odds(odds_payload,game.pitcher_name)\n'''
new = '''odds_events,odds_err=get_odds_events(); odds_event_id=find_odds_event(odds_events,game)\nodds_payload_key=f"projection_live_odds:{game.key}"\nodds_quota_key=f"projection_live_odds_quota:{game.key}"\nodds_payload=st.session_state.get(odds_payload_key,{})\nif odds_event_id:\n    with st.sidebar:\n        st.markdown("#### 💳 Odds API Credit Saver")\n        st.caption("Paid odds are OFF by default. Main Strikeouts + Outs + Hits only; one US region; up to 3 credits when you press load. Alternate markets stay off.")\n        load_live_odds=st.button("LOAD LIVE ODDS · ≤3 credits",key=f"load_live_odds:{game.key}",use_container_width=True)\n    if load_live_odds:\n        loaded_payload,prop_err,quota=get_event_props(odds_event_id)\n        if loaded_payload:\n            odds_payload=loaded_payload\n            st.session_state[odds_payload_key]=loaded_payload\n        if quota:\n            st.session_state[odds_quota_key]=quota\n        odds_err=prop_err if prop_err else odds_err\nelse:\n    odds_payload=[]\n    odds_err=odds_err if odds_err else "No matching Odds API event found for this MLB game."\nquota_view=st.session_state.get(odds_quota_key,{})\nif quota_view:\n    with st.sidebar:\n        st.caption(f"Last paid load: {quota_view.get('last','—')} credit(s) · {quota_view.get('remaining','—')} remaining · {quota_view.get('used','—')} used.")\nif not odds_payload and not odds_err:\n    odds_err="Live sportsbook prices not loaded. Credit Saver is ON; the baseball projection does not need sportsbook data."\nodds_rows=extract_player_odds(odds_payload,game.pitcher_name)\n'''
if old not in app:
    raise SystemExit("Projection automatic odds call anchor not found")
app = app.replace(old, new, 1)
APP.write_text(app, encoding="utf-8")

TEST.write_text('''from pathlib import Path\n\n\ndef test_top_plays_credit_saver_requires_manual_paid_load_and_main_markets_only():\n    source = Path("pages/6_Top_Plays.py").read_text(encoding="utf-8")\n    assert 'MAIN_MARKET_KEYS = {' in source\n    assert '"Strikeouts": "pitcher_strikeouts"' in source\n    assert '"Total Outs": "pitcher_outs"' in source\n    assert '"Hits Allowed": "pitcher_hits_allowed"' in source\n    assert 'Load / reuse live Top 5 prices' in source\n    assert 'estimated_credits = sum(len(markets) for markets in request_plan.values())' in source\n    assert 'event_props(api_key, event_id, tuple(sorted(market_keys)))' in source\n    assert 'pitcher_strikeouts,pitcher_strikeouts_alternate' not in source\n    assert 'Alternate markets are disabled by default.' in source\n\n\ndef test_projection_page_credit_saver_has_no_automatic_paid_prop_call():\n    source = Path("streamlit_app.py").read_text(encoding="utf-8")\n    assert 'MAIN_PROP_MARKETS="pitcher_strikeouts,pitcher_outs,pitcher_hits_allowed"' in source\n    assert 'LOAD LIVE ODDS · ≤3 credits' in source\n    assert 'Paid odds are OFF by default.' in source\n    assert 'Alternate markets stay off.' in source\n    automatic = 'if odds_event_id: odds_payload,prop_err=get_event_props(odds_event_id)'\n    assert automatic not in source\n\n\ndef test_paid_odds_calls_cache_for_fifteen_minutes_and_track_quota_headers():\n    top = Path("pages/6_Top_Plays.py").read_text(encoding="utf-8")\n    app = Path("streamlit_app.py").read_text(encoding="utf-8")\n    assert '@st.cache_data(ttl=900, show_spinner=False)\\ndef event_props' in top\n    assert '@st.cache_data(ttl=900,show_spinner=False)\\ndef get_event_props' in app\n    for source in (top, app):\n        assert 'x-requests-remaining' in source\n        assert 'x-requests-used' in source\n        assert 'x-requests-last' in source\n''', encoding="utf-8")
